                        r[k,i] = simplify(r[k,i])
                    if r[k,i] != 0:
                        break
                if k == r.lines - 1 and r[k,i] == 0:
                    continue
                r.row_swap(pivots,k)
            scale = r[pivots,i]
            r.row(pivots, lambda x, _: x/scale)
            for j in range(r.lines):
                if j == pivots:
                    continue
                scale = r[j,i]
                r.row(j, lambda x, k: x - r[pivots,k]*scale)
